import{OCEAN_CONFIG as s}from"./config.min.js";function c(n,t,e){if(t<=n)return e>=t?1:0;const r=Math.max(0,Math.min(1,(e-n)/(t-n)));return r*r*(3-2*r)}function m(n,t,e){return n+(t-n)*e}export function arcProgress(n,t=s.storm){const e=t.seconds>0?t.seconds:1;return Math.max(0,Math.min(1,n/e))}export function stageAt(n,t=s.storm){const e=t.stages;let r=e[0];for(let a=0;a<e.length;a++)n>=e[a].from&&(r=e[a]);return r}export function stageProgress(n,t=s.storm){const e=t.stages;for(let r=0;r<e.length;r++){const a=e[r].from,o=r+1<e.length?e[r+1].from:t.seconds;if(n>=a&&(n<o||r===e.length-1))return o<=a?1:Math.max(0,Math.min(1,(n-a)/(o-a)))}return 0}export function swellAt(n,t=s.storm){return curveAt(n,t.swell,t)}export function leanAt(n,t=s.storm){return curveAt(n,t.lean,t)}export function gloomAt(n,t=s.storm){return curveAt(n,t.gloom,t)}export function surgeAt(n,t=s.storm){return curveAt(n,t.surge,t)}export function curveAt(n,t,e=s.storm){if(!t||t.length===0)return 0;if(t.length===1)return t[0].value;const r=Math.max(0,Math.min(e.seconds,n));if(r<=t[0].at)return t[0].value;const a=t[t.length-1];if(r>=a.at)return a.value;for(let o=1;o<t.length;o++)if(r<=t[o].at){const u=t[o-1],l=t[o];return m(u.value,l.value,c(u.at,l.at,r))}return a.value}export function engulfAt(n,t=s){const e=t.camera.height,r=t.storm.engulfWashMetres;return c(e,e+r,n)}export function washEnvelope(n,t,e,r=s.storm){const a=n&&typeof n=="object"?n:{wash:0,target:0,attacking:!1},o=Math.max(0,e),u=r.washReleaseSeconds>0?r.washReleaseSeconds:1,l=r.washAttackSeconds>0?r.washAttackSeconds:.2,h=t-a.target;let i=a.attacking;o>0&&h/o>1/u&&(i=!0);let f;return i?(f=Math.min(t,a.wash+o/l),f>=t-1e-9&&(i=!1)):f=Math.max(0,a.wash-o/u),{wash:f,target:t,attacking:i}}export function frontAt(n,t=s.storm){const e=t.tsunami;if(!e||n<e.startAt)return null;const r=e.arriveAt-e.startAt,a=r>0?Math.min(1,(n-e.startAt)/r):1;return{z:e.fromZ+(e.toZ-e.fromZ)*a,rise:e.rise*c(0,.25,a),width:e.frontWidth,foam:e.frontFoam*c(0,.15,a),swellBehind:e.swellBehind}}export function frontLevelAt(n,t){return t?t.rise*(1-c(t.z-t.width,t.z+t.width,n)):0}export function surfaceAtCamera(n,t=s){const{beach:e,camera:r}=t,a=(r.z-e.shoreZ)*e.slope;return Math.max(a,n)}export function fadeAt(n,t=s.storm){const e=t.seconds-t.fadeSeconds;return c(e,t.seconds,n)}export function stormStateAt(n,t=s,e=null){const r=t.storm,a=surgeAt(n,r),o=frontAt(n,r),u=a+frontLevelAt(t.camera.z,o),l=e??surfaceAtCamera(u,t);return{seconds:n,progress:arcProgress(n,r),stage:stageAt(n,r).name,swell:swellAt(n,r),lean:leanAt(n,r),gloom:gloomAt(n,r),surge:a,front:o,engulf:engulfAt(l,t),fade:fadeAt(n,r),finished:n>=r.seconds}}
